package app.kinnect.audit;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;
public class LiveGamePickerAudit extends Instrumentation {
 int checks;public void onCreate(Bundle b){super.onCreate(b);start();}void check(boolean ok,String why){if(!ok)throw new AssertionError(why);checks++;}Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}Object call(Object o,String n,Class<?>[] ts,Object...a)throws Exception{Method m=o.getClass().getDeclaredMethod(n,ts);m.setAccessible(true);return m.invoke(o,a);}View find(View v,String value){if(value.equals(v.getContentDescription())||v instanceof TextView&&value.equals(((TextView)v).getText().toString()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View r=find(((ViewGroup)v).getChildAt(i),value);if(r!=null)return r;}return null;}void tap(String label)throws Exception{Thread.sleep(120);AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();for(AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText(label)){if(n.getText()==null||!label.equals(n.getText().toString()))continue;while(n!=null&&!n.isClickable())n=n.getParent();if(n!=null){n.performAction(16);return;}}throw new AssertionError(label);}AccessibilityNodeInfo input(AccessibilityNodeInfo n){if(n==null)return null;if(n.isEditable())return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo r=input(n.getChild(i));if(r!=null)return r;}return null;}void shot(Activity a,String name)throws Exception{Thread.sleep(120);try(FileOutputStream f=new FileOutputStream(new File(a.getExternalFilesDir(null),name))){getUiAutomation().takeScreenshot().compress(Bitmap.CompressFormat.PNG,100,f);}}
 public void onStart(){Bundle out=new Bundle();Activity a=null;try{ClassLoader cl=getTargetContext().getClassLoader();Class<?> apiType=cl.loadClass("app.kinnect.live.NativeApi");Object api=apiType.getField("shared").get(null);call(api,"configure",new Class[]{String.class},"https://127.0.0.1:9");Class<?> language=cl.loadClass("app.kinnect.live.I18n");Method select=language.getDeclaredMethod("select",Context.class,String.class);select.setAccessible(true);select.invoke(null,getTargetContext(),"vi");a=startActivitySync(new Intent().setClassName("app.kinnect.live","app.kinnect.live.LiveActivity").putExtra("host",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final Activity live=a;runOnMainSync(()->{try{set(live,"liveMode","game");call(live,"showGamePreview",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(150);View choice=find(live.getWindow().getDecorView(),"Chọn game");check(choice instanceof EditText,"Game field missing");check(!choice.isFocusable(),"Game field should open a list, not keyboard");runOnMainSync(()->choice.performClick());Thread.sleep(200);Object picker=get(live,"gamePicker");Dialog dialog=(Dialog)get(picker,"dialog");LinearLayout rows=(LinearLayout)get(picker,"results");check(rows.getChildCount()==12,"Curated catalog count");for(String game:new String[]{"Liên Quân Mobile","Free Fire","PUBG MOBILE VN","Roblox VN"})check(find(dialog.getWindow().getDecorView(),game)!=null,"Missing suggested game "+game);shot(live,"game29-list.png");EditText search=(EditText)find(dialog.getWindow().getDecorView(),"Tìm game");final EditText initialSearch=search;runOnMainSync(()->initialSearch.setText("toc chien"));Thread.sleep(100);check(rows.getChildCount()==1,"Accentless search should find Tốc Chiến");ViewGroup row=(ViewGroup)rows.getChildAt(0);TextView title=(TextView)((ViewGroup)row.getChildAt(1)).getChildAt(0);check(title.getText().toString().contains("Tốc Chiến"),"Wrong search result");check(title.getLayout().getHeight()<=title.getHeight()-title.getPaddingTop()-title.getPaddingBottom(),"Long game title clipped/font130");runOnMainSync(()->row.performClick());check(get(live,"gameTitle").equals("Liên Minh Huyền Thoại: Tốc Chiến"),"Selection not stored for Live payload");check(((EditText)choice).getText().toString().equals(get(live,"gameTitle")),"Selected game field stale");runOnMainSync(()->choice.performClick());Thread.sleep(100);picker=get(live,"gamePicker");dialog=(Dialog)get(picker,"dialog");search=(EditText)find(dialog.getWindow().getDecorView(),"Tìm game");final EditText s=search;runOnMainSync(()->s.setText("zzzz-no-result"));Thread.sleep(100);check(get(live,"gameTitle").equals("Liên Minh Huyền Thoại: Tốc Chiến"),"Searching mutated selection");check(find(dialog.getWindow().getDecorView(),"Không tìm thấy game. Chọn Game khác để nhập tên.")!=null,"Empty state missing");tap("Game khác");Thread.sleep(100);AccessibilityNodeInfo edit=input(getUiAutomation().getRootInActiveWindow());check(edit!=null,"Custom game input missing");Bundle value=new Bundle();value.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,"Game thử nghiệm");edit.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,value);tap("Chọn");check(get(live,"gameTitle").equals("Game thử nghiệm"),"Custom game selection");runOnMainSync(()->choice.performClick());Thread.sleep(100);tap("Không chọn");check(get(live,"gameTitle").equals(""),"Clear selection");out.putString("result","PASS "+checks+":12 suggested games, list entry, accentless search, long-label bounds/font130, selected title propagation, search preserves selection, empty state, custom name and clear. No games launched or broadcast.");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("error",e.toString());finish(Activity.RESULT_CANCELED,out);}finally{final Activity last=a;if(last!=null)runOnMainSync(()->last.finish());}}
}
